// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != c.owner());
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        assertTrue(ok == false && balanceAfter == balanceBefore);
    }
}
